UPDATE billable_usage_remittance
      SET last_modified = updated_at AT TIME ZONE 'UTC'
      WHERE last_modified IS NULL AND updated_at IS NOT NULL;

CREATE TRIGGER trg_billable_usage_remittance_last_modified
      BEFORE INSERT OR UPDATE ON billable_usage_remittance
      FOR EACH ROW EXECUTE FUNCTION swatch_billable_usage_update_last_modified_column();

UPDATE billable_usage_remittance
      SET last_modified = CURRENT_TIMESTAMP
      WHERE last_modified IS NULL;
